def top_3_produtos(vendas: list[dict]) -> list[tuple[str, int]]:
    """Retorna os 3 produtos com maior quantidade total vendida."""
    total_por_produto: dict[str, int] = {}
    for venda in vendas:
        produto = venda['produto']
        quantidade = venda['quantidade']
        total_por_produto[produto] = total_por_produto.get(produto, 0) + quantidade

    return sorted(total_por_produto.items(), key=lambda item: (-item[1], item[0]))[:3]
